const items = $input.all().map(item => item.json);

var personalInfo = {};

function applyRow(data, row) {
  const pathParts = row.col_4.split("_");

  let current = data;

  pathParts.forEach((part, index) => {
    const isArray = part.endsWith("[]");
    const key = isArray ? part.slice(0, -2) : part;
    const isLast = index === pathParts.length - 1;

    // Ensure structure exists
    if (!current[key]) {
      current[key] = isArray ? [] : {};
    }

    if (isLast) {
      let value = row.col_2;

      if (isArray) {
        // Split values if final is array
        const values = value.split("|").map(v => v.trim());
        current[key].push(...values);
      } else {
        current[key] = value;
      }
    } else {
      if (isArray) {
        // Ensure at least one object exists in array
        if (current[key].length === 0) {
          current[key].push({});
        }
        // Move into the last object in the array
        current = current[key][current[key].length - 1];
      } else {
        current = current[key];
      }
    }
  });

  return data;
}

