function getYearDifference(dateStr) {
  const [month, year] = dateStr.split('/').map(Number);

  // JS months are 0-based (0 = January)
  const date = new Date(year, month - 1);

  const now = new Date();

  let diff = now.getFullYear() - date.getFullYear();

  // Adjust if current month is before the given month
  if (now.getMonth() < (month - 1)) {
    diff--;
  }

  return diff;
}


