/*
for each skill:
		add recency: "CURRENT|RECENT|HISTORICAL"
		add to each array, if 0-1 years back it is current, if it is 2-4 is recent, 5+ is historical
*/

var currentMaxYearsAgo = 1;
var recentMaxYearsAgo = 2;

function yearsAgo(item) {
    return new Date().getFullYear() - parseInt(item.lastUsed, 10);
}

function isCurrent(item) {
    return yearsAgo(item) <= currentMaxYearsAgo;
}

function isRecent(item) {
    return yearsAgo(item) <= recentMaxYearsAgo;
}

var result = {
  		byProficiency: {},
		byCategory: {},
		current: [],
		recent: [],
		historical: [],
        all: []
}

for(var item of items){
    result.all.push(item);
    if(!Object.hasOwn(result.byProficiency, item.proficiencyLevel)){
      result.byProficiency[item.proficiencyLevel] = [];
    }
    result.byProficiency[item.proficiencyLevel].push(item);

    if(!Object.hasOwn(result.byCategory, item.category)){
      result.byCategory[item.category] = [];
    }
    result.byCategory[item.category].push(item);

    if(isCurrent(item)){
      item.recency = "CURRENT";
      result.current.push(item);
    }
    else if(isRecent(item)){
       item.recency = "RECENT";
      result.recent.push(item);     
    }
    else {
      item.recency = "HISTORICAL";
      result.historical.push(item);    
    } 
}

return [{ json: {skills: result} }];

