// ------- functions -----------------------------------
function buildSuitedPositionsIndex(allJobs, threshold = 80) {

  // Step 1: collect all position matches across all jobs, weighted by recency
  const positionScores = {};

  for (const job of allJobs) {
    if (!job.possiblePositions) continue;

    // Recency weight — linear decay over 10 years, floor at 0.2
    const yearsAgo       = job.yearsAgo || 0;
    const recencyWeight  = Math.max(0.2, 1 - (yearsAgo * 0.05));
    // yearsAgo=0  → weight=1.0  (current job)
    // yearsAgo=3  → weight=0.76
    // yearsAgo=5  → weight=0.60
    // yearsAgo=10 → weight=0.20

    for (const match of job.possiblePositions) {
      const key = match.jobTitle.toLowerCase().trim();

      if (!positionScores[key]) {
        positionScores[key] = {
          position:       match.jobTitle,
          weightedScores: [],
          seniorityLevels: [],
          tailorInstructions: [],
          bestMatchJob:   null,
          bestMatchScore: 0
        };
      }

      const weightedScore = match.matchPercentage * recencyWeight;

      positionScores[key].weightedScores.push(weightedScore);
      positionScores[key].seniorityLevels.push(match.seniorityLevel);
      positionScores[key].tailorInstructions.push({
        job:          job.company + ' — ' + job.jobTitle,
        instructions: match.tailorInstructions,
        weight:       recencyWeight
      });

      // Track which job gives the strongest match for this position
      if (weightedScore > positionScores[key].bestMatchScore) {
        positionScores[key].bestMatchScore = weightedScore;
        positionScores[key].bestMatchJob   = job.company + ' — ' + job.title;
      }
    }
  }

  // Step 2: aggregate scores per position
  const aggregated = Object.values(positionScores).map(p => {
    const avgWeightedScore = p.weightedScores.reduce((a, b) => a + b, 0)
                           / p.weightedScores.length;

    // Seniority: take the highest level seen across jobs
    const seniorityRank = { 'JUNIOR': 1, 'MIDLEVEL': 2, 'SENIOR': 3, 'LEAD': 4, 'PRINCIPAL': 5 };
    const highestSeniority = p.seniorityLevels
      .sort((a, b) => (seniorityRank[b] || 0) - (seniorityRank[a] || 0))[0];

    // Tailor instructions: take the one from the highest-weighted job
    const bestInstructions = p.tailorInstructions
      .sort((a, b) => b.weight - a.weight)[0]?.instructions || '';

    return {
      position:           p.position,
      score:              Math.round(avgWeightedScore),
      best_match_job:     p.bestMatchJob,
      seniority_level:    highestSeniority,
      tailor_instructions: bestInstructions,
      evidence_count:     p.weightedScores.length  // how many jobs support this position
    };
  });

  // Step 3: apply threshold and sort
  return aggregated
    .filter(p => p.score >= threshold)
    .sort((a, b) => b.score - a.score);
}
