function parseDate(str) {
  const [month, year] = str.split("/").map(Number);
  return new Date(year, month - 1);
}

function normalize(str) {
  return str.toLowerCase().trim();
}

function getYearsBetween(startDate, endDate) {
  const start = parseDate(startDate);
  const end = endDate ? parseDate(endDate) : new Date();

  let years = end.getFullYear() - start.getFullYear();

  const m1 = start.getMonth();
  const m2 = end.getMonth();

  if (m2 < m1 || (m2 === m1 && end.getDate() < start.getDate())) {
    years--;
  }

  return Math.max(0, years);
}

function getTotalYearsOfExperience(jobs){
  if (!jobs || jobs.length === 0) return 0;

  let earliestStart = null;
  let latestEnd = null;

  jobs.forEach(job => {
    const start = parseDate(job.startDate);
    const end = job.endDate ? parseDate(job.endDate) : new Date(); // handle current job

    if (!earliestStart || start < earliestStart) {
      earliestStart = start;
    }

    if (!latestEnd || end > latestEnd) {
      latestEnd = end;
    }
  });

  if (!earliestStart || !latestEnd) return 0;

  let years = latestEnd.getFullYear() - earliestStart.getFullYear();

  // Adjust if the last year isn't fully completed
  const m1 = earliestStart.getMonth();
  const m2 = latestEnd.getMonth();

  if (m2 < m1 || (m2 === m1 && latestEnd.getDate() < earliestStart.getDate())) {
    years--;
  }
  return years;
}

function deriveSeniority(totalYears, hasLeadership, maxTeamSize, selfAssessed) {
  // Self-assessed override takes priority if filled in
  if (selfAssessed && selfAssessed.trim().length > 0) return selfAssessed;

  if (totalYears >= 12 && maxTeamSize >= 8)  return 'Principal';
  if (totalYears >= 10 && hasLeadership)      return 'Staff';
  if (totalYears >= 7  && hasLeadership)      return 'Lead';
  if (totalYears >= 7)                        return 'Senior';
  if (totalYears >= 3)                        return 'Mid';
  return 'Junior';
}

function getPrimaryAndSecondaryDomains(workExperiences) {
  const domainWeightIndex = {};

  workExperiences.forEach(job => {
    if (!job.industry || !job.startDate) return;

    const domain = normalize(job.industry);
    const years = getYearsBetween(job.startDate, job.endDate);

    if (!domainWeightIndex[domain]) {
      domainWeightIndex[domain] = 0;
    }

    domainWeightIndex[domain] += years;
  });

  // Convert to sortable array
  const sortedDomains = Object.entries(domainWeightIndex)
    .sort((a, b) => b[1] - a[1]);

  return {
    primaryDomain: sortedDomains[0]?.[0] || null,
    secondaryDomains: sortedDomains.slice(1).map(([domain]) => domain)
  };
}

function getStrongestTechnicalAreas(skills){

  const proficiencyWeight = {
  'expert':       4,
  'advanced':     3,
  'intermediate': 2,
  'basic':        1
};

const categoryScores = {};
for (const skill of skills) {
  const cat    = skill['category'];
  const weight = proficiencyWeight[skill['proficiencyLevel']] || 0;
  // Also weight by recency
  const recencyMultiplier = 
    skill.recency === 'CURRENT'    ? 1.0 :
    skill.recency === 'RECENT'     ? 0.7 :
                                     0.3;

  categoryScores[cat] = (categoryScores[cat] || 0) + (weight * recencyMultiplier);
}

// Top 3-4 categories by score
return Object.entries(categoryScores)
  .filter(([cat]) => cat.toLowerCase() !== 'soft skill' && cat.toLowerCase() !== 'methodology')
  .sort((a, b) => b[1] - a[1])
  .slice(0, 4)
  .map(([cat]) => cat);
}

function getStrongestSoftSkills(skills){
    const proficiencyWeight = {
      'expert':       4,
      'advanced':     3,
      'intermediate': 2,
      'basic':        1
    };
  return skills
  .filter(s => s['category'].toLowerCase().trim() === 'soft skill')
  .map(s => ({
    name:   s.name,
    score:  (proficiencyWeight[s.proficiencyLevel.toLowerCase().trim()] || 0)
            * (s.recency === 'CURRENT' ? 1.0 : s.recency === 'RECENT' ? 0.7 : 0.3)
  }))
  .sort((a, b) => b.score - a.score)
  .slice(0, 5)
  .map(s => s.name);
}

function getIndustryExperience(workExperience){
  return [
  ...new Set(
    workExperience
      .map(job => job.industry)
      .filter(Boolean)
  )
];
}

function hasLeadershipExperience(workExperiences) {
  let hasLeadershipExperience = false;
  let maxTeamSizeManaged = 0;

  workExperiences.forEach(job => {
    const direct = Number(job.directReports) || 0;
    const indirect = Number(job.indirectReports) || 0;
    const teamSize = direct + indirect;

    if (teamSize > 0) {
      hasLeadershipExperience = true;
      maxTeamSizeManaged = Math.max(maxTeamSizeManaged, teamSize);
      return;
    }

    // --- Fallback detection (if no report numbers provided) ---
    const title = (job.jobTitle || "").toLowerCase();
